<?php
declare(strict_types=1);require dirname(__DIR__).'/vendor/autoload.php';use App\{Database,Http,Auth};$origin=getenv('FRONTEND_URL')?:'http://localhost:4200';header('Access-Control-Allow-Origin: '.$origin);header('Access-Control-Allow-Credentials: true');header('Access-Control-Allow-Headers: Content-Type');header('Access-Control-Allow-Methods: GET,POST,OPTIONS');if($_SERVER['REQUEST_METHOD']==='OPTIONS'){http_response_code(204);exit;}session_name(getenv('SESSION_NAME')?:'lirandzu_session');session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS']),'samesite'=>'Lax','path'=>'/']);session_start();try{$db=Database::connection();$path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH);$method=$_SERVER['REQUEST_METHOD'];$body=$method==='POST'?Http::body():[];$auth=new Auth($db);if($path==='/api/health')Http::json(['ok'=>true]);if($path==='/api/auth/login'&&$method==='POST')$auth->login($body);if($path==='/api/auth/logout'&&$method==='POST')$auth->logout();if($path==='/api/auth/me')Http::json(['user'=>Http::user()]);if($path==='/api/categories')Http::json(['data'=>$db->query('SELECT id,name,slug FROM categories WHERE active=1 ORDER BY sort_order')->fetchAll()]);if($path==='/api/providers'){$q=trim((string)($_GET['q']??''));$s=$db->prepare("SELECT p.id,p.business_name,p.slug,p.city,p.description,p.indicative_price,p.cover_image,p.verified,p.featured,c.name category FROM providers p JOIN categories c ON c.id=p.category_id WHERE p.status='active' AND (p.business_name LIKE ? OR p.description LIKE ?) ORDER BY p.featured DESC,p.verified DESC LIMIT 100");$s->execute(['%'.$q.'%','%'.$q.'%']);Http::json(['data'=>$s->fetchAll()]);}if($path==='/api/provider-applications'&&$method==='POST'){$n=trim((string)($body['applicant_name']??''));$b=trim((string)($body['business_name']??''));$e=strtolower(trim((string)($body['email']??'')));$ph=trim((string)($body['phone']??''));$c=(int)($body['category_id']??0);$city=trim((string)($body['city']??''));$d=trim((string)($body['description']??''));if(strlen($n)<3||strlen($b)<2||!filter_var($e,FILTER_VALIDATE_EMAIL)||strlen($ph)<8||$c<1||strlen($city)<2||strlen($d)<20)Http::json(['error'=>'Verifique os campos da candidatura'],422);$s=$db->prepare('INSERT INTO provider_applications(applicant_name,business_name,email,phone,category_id,city,description) VALUES(?,?,?,?,?,?,?)');$s->execute([$n,$b,$e,$ph,$c,$city,$d]);Http::json(['ok'=>true,'message'=>'Candidatura recebida para análise'],201);}Http::json(['error'=>'Rota não encontrada'],404);}catch(Throwable $e){error_log((string)$e);Http::json(['error'=>getenv('APP_DEBUG')==='true'?$e->getMessage():'Erro interno'],500);}
